// Parser de mensajes entrantes de Evolution API (Multi-Device QR)
const body = $input.first().json.body || $input.first().json;
const data = body.data || body;

if (!data) {
  return [];
}

const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InBldGNxYWl4emV0d3NkdXNjdnR4Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODk1OTAxNjMsImV4cCI6MjEwNTE2NjE2M30.4vDNJ3nBMi0TQg71KZUpyJdcBWr5zyTDKR92xA4obgM';

// 1. MANEJO DE MENSAJES SALIENTES DE LA SECRETARÍA / OPERADOR (fromMe = true)
if (data.key?.fromMe) {
  const remoteJid = data.key?.remoteJid || '';
  if (remoteJid && !remoteJid.includes('@g.us') && !remoteJid.includes('status@broadcast')) {
    const patientPhone = remoteJid.replace('@s.whatsapp.net', '');
    let msgObj = data.message || {};
    if (msgObj.viewOnceMessage?.message) msgObj = msgObj.viewOnceMessage.message;
    if (msgObj.viewOnceMessageV2?.message) msgObj = msgObj.viewOnceMessageV2.message;
    if (msgObj.ephemeralMessage?.message) msgObj = msgObj.ephemeralMessage.message;

    let secText = '';
    if (msgObj.conversation) secText = msgObj.conversation;
    else if (msgObj.extendedTextMessage?.text) secText = msgObj.extendedTextMessage.text;
    else if (msgObj.imageMessage?.caption) secText = msgObj.imageMessage.caption;
    else if (msgObj.documentMessage?.caption) secText = msgObj.documentMessage.caption;

    if (secText) {
      try {
        await fetch('https://petcqaixzetwsduscvtx.supabase.co/rest/v1/mensajes_chat', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'apikey': SUPABASE_KEY,
            'Authorization': 'Bearer ' + SUPABASE_KEY
          },
          body: JSON.stringify({
            whatsapp_id: patientPhone,
            emisor: 'SECRETARIA',
            contenido: secText
          })
        });

        await fetch('https://petcqaixzetwsduscvtx.supabase.co/rest/v1/pacientes_leads?whatsapp_id=eq.' + patientPhone, {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json',
            'apikey': SUPABASE_KEY,
            'Authorization': 'Bearer ' + SUPABASE_KEY
          },
          body: JSON.stringify({
            estado_atencion: 'ESCALADO_HUMANO',
            ultimo_mensaje: secText,
            updated_at: new Date().toISOString()
          })
        });
      } catch (err) {
        console.warn('Error syncing secretary outbound message:', err);
      }
    }
  }
  return [];
}

const senderRemoteJid = data.key?.remoteJid || '';

// Ignorar grupos o estados
if (!senderRemoteJid || senderRemoteJid.includes('@g.us') || senderRemoteJid.includes('status@broadcast')) {
  return [];
}

const senderPhone = senderRemoteJid.replace('@s.whatsapp.net', '');
const senderName = data.pushName || 'Paciente';
const instanceName = body.instance || 'gonzalez-prato';

// Extraer mensaje
let msgObj = data.message || {};
if (msgObj.viewOnceMessage?.message) msgObj = msgObj.viewOnceMessage.message;
if (msgObj.viewOnceMessageV2?.message) msgObj = msgObj.viewOnceMessageV2.message;
if (msgObj.ephemeralMessage?.message) msgObj = msgObj.ephemeralMessage.message;
if (msgObj.documentWithCaptionMessage?.message) msgObj = msgObj.documentWithCaptionMessage.message;

let userText = '';
let isImage = false;
let mimetype = 'image/jpeg';
let base64Media = data.message?.base64 || data.base64 || body.base64 || msgObj.base64 || msgObj.imageMessage?.base64 || msgObj.documentMessage?.base64 || null;

if (msgObj.conversation) {
  userText = msgObj.conversation;
} else if (msgObj.extendedTextMessage?.text) {
  userText = msgObj.extendedTextMessage.text;
} else if (msgObj.imageMessage) {
  isImage = true;
  mimetype = msgObj.imageMessage.mimetype || 'image/jpeg';
  userText = msgObj.imageMessage.caption || '[Foto de orden médica / récipe]';
  if (!base64Media && msgObj.imageMessage.base64) base64Media = msgObj.imageMessage.base64;
} else if (msgObj.documentMessage && (msgObj.documentMessage.mimetype?.startsWith('image/') || msgObj.documentMessage.mimetype === 'application/pdf')) {
  isImage = true;
  mimetype = msgObj.documentMessage.mimetype;
  userText = msgObj.documentMessage.caption || '[Documento / Récipe adjunto]';
  if (!base64Media && msgObj.documentMessage.base64) base64Media = msgObj.documentMessage.base64;
} else if (msgObj.audioMessage) {
  userText = '[Nota de voz del paciente]';
}

if (!userText && !isImage) {
  return [];
}

// 2. RECUPERACIÓN DE BASE64 DESDE EVOLUTION API (SI APLICA)
if (isImage && !base64Media) {
  try {
    const mediaRes = await fetch('http://86.48.20.190:8080/chat/getBase64FromMediaMessage/' + instanceName, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'apikey': 'GonzalezPratoSecret2026'
      },
      body: JSON.stringify({
        message: {
          key: data.key,
          message: data.message || msgObj
        },
        convertToMp4: false
      })
    });
    const mediaData = await mediaRes.json();
    if (mediaData && mediaData.base64) {
      base64Media = mediaData.base64;
      if (mediaData.mimetype) mimetype = mediaData.mimetype;
    }
  } catch (err) {
    console.warn('Error fetching media base64 from Evolution API:', err);
  }
}

// 3. ANÁLISIS MULTIMODAL CON GEMINI VISION PARA TRANSCRIPCIÓN DETERMINISTA DE RÉCIPES
if (isImage && base64Media) {
  try {
    const cleanBase64 = base64Media.includes(',') ? base64Media.split(',')[1] : base64Media;
    const cleanMime = (mimetype && mimetype.includes(';')) ? mimetype.split(';')[0] : (mimetype || 'image/jpeg');

    const ocrUrl = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent?key=' + Buffer.from('QVEuQWI4Uk42SkxfM2ZQUjVyN1N1cXQzc1hGdWRjZjJZOFozNEVzRzdnV05nN3pXM1p1QXc=', 'base64').toString();
    const ocrRes = await fetch(ocrUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{
          parts: [
            { text: "Eres un bioanalista y especialista clínico experto en lectura de órdenes médicas y récipes manuscritos. Analiza con sumo cuidado esta imagen adjunta y extrae la lista exacta de todos los exámenes de laboratorio indicados por el médico para cotizarlos en nuestro laboratorio. Transcribe cada examen claramente sin agregar precios ni inventar diagnósticos." },
            { inline_data: { mime_type: cleanMime, data: cleanBase64 } }
          ]
        }],
        generationConfig: { temperature: 0.0, topP: 0.1 }
      })
    });
    const ocrData = await ocrRes.json();
    const extractedText = ocrData.candidates?.[0]?.content?.parts?.[0]?.text || '';
    if (extractedText) {
      userText = 'He recibido la orden médica / récipe adjunto del paciente.\nExámenes identificados en la imagen del récipe:\n' + extractedText + (userText && !userText.includes('[Foto') ? '\nNota adicional del paciente: ' + userText : '');
    }
  } catch (e) {
    console.warn('OCR Vision error:', e);
  }
}

// 4. CONSULTAS PARALELIZADAS A SUPABASE (Lead Status + Catálogo Oficial)
let leadStatus = 'BOT_ACTIVO';
let catalogPromptText = '';

const [leadRes, catRes] = await Promise.all([
  fetch('https://petcqaixzetwsduscvtx.supabase.co/rest/v1/pacientes_leads?whatsapp_id=eq.' + senderPhone + '&select=estado_atencion', {
    headers: { 'apikey': SUPABASE_KEY }
  }).catch(e => {
    console.warn('Error fetching lead status:', e);
    return null;
  }),
  fetch('https://petcqaixzetwsduscvtx.supabase.co/rest/v1/examenes?activo=eq.true&select=categoria,nombre_examen,sinonimos,costo_usd,requisitos_preanaliticos,tipo_muestra,notas&order=categoria.asc,nombre_examen.asc', {
    headers: { 'apikey': SUPABASE_KEY }
  }).catch(e => {
    console.warn('Error fetching parallel Supabase catalog:', e);
    return null;
  })
]);

if (leadRes && leadRes.ok) {
  try {
    const leadRows = await leadRes.json();
    if (Array.isArray(leadRows) && leadRows.length > 0 && leadRows[0].estado_atencion) {
      leadStatus = leadRows[0].estado_atencion;
    }
  } catch (err) {
    console.warn('Error parsing lead status:', err);
  }
}

if (catRes && catRes.ok) {
  try {
    const catData = await catRes.json();
    if (Array.isArray(catData)) {
      catalogPromptText = catData.map(e => {
        const syn = (Array.isArray(e.sinonimos) && e.sinonimos.length > 0) ? ` [Sinónimos: ${e.sinonimos.join(', ')}]` : '';
        const notes = e.notas ? ` | Notas: ${e.notas}` : '';
        return `• ${e.nombre_examen}${syn} (${e.categoria}): $${Number(e.costo_usd).toFixed(2)} USD | Muestra: ${e.tipo_muestra || 'Sangre'} | Requisitos: ${e.requisitos_preanaliticos || 'Ayuno habitual'}${notes}`;
      }).join('\n');
    }
  } catch (err) {
    console.warn('Error parsing catalog JSON:', err);
  }
}

const botActive = (leadStatus !== 'ESCALADO_HUMANO' && leadStatus !== 'FINALIZADO');

if (!botActive) {
  try {
    await fetch('https://petcqaixzetwsduscvtx.supabase.co/rest/v1/pacientes_leads?on_conflict=whatsapp_id', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'apikey': SUPABASE_KEY,
        'Authorization': 'Bearer ' + SUPABASE_KEY,
        'Prefer': 'resolution=merge-duplicates'
      },
      body: JSON.stringify({
        whatsapp_id: senderPhone,
        nombre_completo: senderName,
        ultimo_mensaje: userText,
        updated_at: new Date().toISOString()
      })
    });

    await fetch('https://petcqaixzetwsduscvtx.supabase.co/rest/v1/mensajes_chat', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'apikey': SUPABASE_KEY,
        'Authorization': 'Bearer ' + SUPABASE_KEY
      },
      body: JSON.stringify({
        whatsapp_id: senderPhone,
        emisor: 'PACIENTE',
        contenido: userText
      })
    });
  } catch (e) {
    console.warn('Error saving patient message during paused bot mode:', e);
  }
}

// 5. CÁLCULO EXACTO DE HORARIO LABORAL (Mérida / Venezuela UTC-4)
const now = new Date();
const vzlaTimeStr = now.toLocaleString('en-US', { timeZone: 'America/Caracas' });
const vzlaDate = new Date(vzlaTimeStr);
const dayOfWeek = vzlaDate.getDay();
const currentHour = vzlaDate.getHours();
const currentMinute = vzlaDate.getMinutes();
const totalMinutes = currentHour * 60 + currentMinute;

let isOpen = false;
let nextOpening = 'Mañana a las 7:00 AM';

if (dayOfWeek >= 1 && dayOfWeek <= 5) {
  isOpen = totalMinutes >= 420 && totalMinutes < 900; // Lun-Vie 7:00 AM a 3:00 PM
  if (!isOpen) {
    if (totalMinutes < 420) {
      nextOpening = 'Hoy a las 7:00 AM';
    } else if (dayOfWeek === 5) {
      nextOpening = 'Sábado a las 8:00 AM';
    } else {
      nextOpening = 'Mañana a las 7:00 AM';
    }
  }
} else if (dayOfWeek === 6) {
  isOpen = totalMinutes >= 480 && totalMinutes < 780; // Sáb 8:00 AM a 1:00 PM
  if (!isOpen) {
    if (totalMinutes < 480) {
      nextOpening = 'Hoy a las 8:00 AM';
    } else {
      nextOpening = 'Lunes a las 7:00 AM';
    }
  }
} else {
  isOpen = false;
  nextOpening = 'Lunes a las 7:00 AM';
}

const currentFormattedTime = vzlaDate.toLocaleTimeString('es-VE', { hour: '2-digit', minute: '2-digit', hour12: true });
const dayNames = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
const currentDayName = dayNames[dayOfWeek];

// 6. CONSTRUCCIÓN DEL SYSTEM PROMPT DETERMINISTA 100% SUPABASE (SIN PRECIOS QUEMADOS)
const completeSystemPrompt = `Eres el Operador Principal y Asistente Clínico Virtual Oficial 24/7 de GONZALEZ-PRATO Laboratorio (Directora Técnica: Lic. Luisa Carolina González Ramírez, Mérida, Venezuela).

HORARIOS OFICIALES DE ATENCIÓN EN SEDE:
- Lunes a Viernes: 7:00 AM a 3:00 PM.
- Sábados: 8:00 AM a 1:00 PM.
- Domingos: Cerrado.

CONTEXTO TEMPORAL ACTUAL (VENEZUELA):
- Hoy es: ${currentDayName}
- Hora actual: ${currentFormattedTime}
- Estado de sede física: ${isOpen ? 'ABIERTO EN HORARIO LABORAL' : 'CERRADO (FUERA DE HORARIO DE ATENCIÓN HUMANA)'}
- Próxima apertura de sede: ${nextOpening}

TARIFARIO OFICIAL VIGENTE EXTRAÍDO DIRECTAMENTE DE LA BASE DE DATOS SUPABASE:
${catalogPromptText}

DIRECTIVAS DE DETERMINISMO ABSOLUTO Y CERO ALUCINACIONES:
1. TU ÚNICA FUENTE DE VERDAD sobre exámenes, precios, tipos de muestra y requisitos preanalíticos es el TARIFARIO OFICIAL extraído arriba de la base de datos.
2. TIENES ESTRICTAMENTE PROHIBIDO cotizar, inventar, especular o suponer precios, pruebas o requisitos usando conocimiento preentrenado o memoria previa.
3. RUTA DE ESCAPE OBLIGATORIA (EXAMEN NO ENCONTRADO):
   Si el paciente solicita un examen que NO está listado textualmente ni como sinónimo en el tarifario de arriba:
   - DEBES responder textualmente: "Actualmente no dispongo del precio de este examen en mi base de datos automatizada. Por favor, aguarde un momento para que un operador humano le asista."
   - DEBES ejecutar de inmediato la herramienta 'activar_human_handover_alarma'.
   - NUNCA inventes un costo ni afirmes falsamente que no lo realizamos sin consultar a secretaría.
4. SI EL EXAMEN SÍ APARECE EN EL TARIFARIO:
   - Afirma con total seguridad que sí lo realizamos.
   - Cotízalo usando el monto exacto en $[Monto] USD registrado en el tarifario. PROHIBIDO alterar centavos o redondear.
   - Incluye el tipo de muestra y los requisitos de preparación/ayuno indicados en la base de datos.
5. PRECIOS ESTRICTAMENTE EN DÓLARES ($ USD):
   - Todo cálculo total debe basarse únicamente en la suma matemática de los valores exactos del tarifario.
   - Informa amablemente que también aceptamos Bolívares (Bs.) calculados a la tasa oficial del Banco Central de Venezuela (BCV) del día, Pago Móvil, Punto de Venta, Transferencia y Efectivo.

REGLAS INSTITUCIONALES Y LOGÍSTICA (SOLO LÓGICA, CERO PRECIOS HARDCODEADOS):
- EXÁMENES EXTERNOS / CONVENIO TORRE CARACAS: Si la nota del examen en el tarifario indica que es remitido a Caracas (ej. paneles RAST, perfiles genéticos/inmunes especiales), informa:
  "Estos exámenes son remitidos a un laboratorio en Caracas, por lo tanto, Gonzalez Prato Laboratorio actúa como enlace para la recolección y envío de las muestras. En consecuencia, el resultado llega vía correo electrónico y se le remite al paciente usando esa misma modalidad."
  y ejecuta 'activar_human_handover_alarma'.
- ESTUDIOS MICOLÓGICOS Y DEMODEX: Para cualquier cultivo micológico, directo KOH o estudio de ácaros Demodex, aclara que la toma de muestra es OBLIGATORIAMENTE CON PREVIA CITA con la micóloga y ejecuta 'activar_human_handover_alarma'.
- ATENCIÓN POR ORDEN DE LLEGADA: La toma de muestras general es por orden de llegada (a partir de las 7:00 AM Lun-Vie y 8:00 AM Sáb).
- SERVICIO A DOMICILIO: Disponible exclusivamente Lunes, Martes y Jueves. En el Municipio Libertador de Mérida es GRATUITO (sin costo adicional). En clínicas/hospitales el familiar debe acompañar a la analista.
- TIEMPO DE ENTREGA: Rutina, química, hematología, hormonas y serología se entregan el MISMO DÍA (salvo eventualidad mayor). Cultivos bacteriológicos demoran de 3 a 8 días.
- SEGUROS MÉDICOS: No tenemos convenios directos con seguros; se emite factura para reembolso.
- RECEPCIÓN DE HECES: Lunes a Viernes hasta las 2:30 PM | Sábados hasta las 12:30 PM.
- ENVÍO DE RESULTADOS: Notificación automática por WhatsApp con enlace y PDF (advertir al paciente NO tener activados 'mensajes temporales').
- SERVICIOS NO REALIZADOS: NO realizamos ecografías, ultrasonidos, radiografías, biopsias, endoscopias ni citas médicas (somos exclusivamente laboratorio clínico).
- ESCALADO A ASESOR HUMANO: Si el paciente escribe "secretaria", "persona", "hablar con alguien", "humano" o hace un reclamo, responde cortésmente transfiriendo el caso y ejecuta 'activar_human_handover_alarma'.

FORMATO DE COTIZACIÓN OBLIGATORIO:
• [Nombre del Examen]
  - Precio: $[Monto] USD
  - Muestra: [Tipo de muestra según tarifario]
  - Requisitos: [Ayuno / Preparación según tarifario]

──────────────────────────
Total a Cancelar: $[Total] USD
(Aceptamos también Bolívares a tasa oficial BCV, Pago Móvil, Punto de Venta y Transferencia)

📍 Sede: Urb. El Encanto, Clínica del Niño, Sótano 2 (detrás de la Contraloría del Estado Mérida).
⏰ Horarios: Lunes a Viernes de 7:00 AM a 3:00 PM | Sábados de 8:00 AM a 1:00 PM.`;

return [{
  json: {
    senderRemoteJid,
    senderPhone,
    senderName,
    userText,
    isImage,
    base64Media,
    instance: instanceName,
    leadStatus,
    botActive,
    completeSystemPrompt,
    scheduleContext: {
      isOpen,
      nextOpening,
      currentDayName,
      currentFormattedTime
    }
  }
}];

const senderPhone = $('Parsear Mensaje Evolution API').item.json.senderPhone;
const scheduleCtx = $('Parsear Mensaje Evolution API').item.json.scheduleContext;
const estadoAtencion = (scheduleCtx && scheduleCtx.isOpen) ? 'ESCALADO_HUMANO' : 'ESCALADO_FUERA_HORARIO';

try {
  await fetch('https://petcqaixzetwsduscvtx.supabase.co/rest/v1/pacientes_leads?whatsapp_id=eq.' + senderPhone, {
    method: 'PATCH',
    headers: {
      'Content-Type': 'application/json',
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InBldGNxYWl4emV0d3NkdXNjdnR4Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODk1OTAxNjMsImV4cCI6MjEwNTE2NjE2M30.4vDNJ3nBMi0TQg71KZUpyJdcBWr5zyTDKR92xA4obgM',
      'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InBldGNxYWl4emV0d3NkdXNjdnR4Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODk1OTAxNjMsImV4cCI6MjEwNTE2NjE2M30.4vDNJ3nBMi0TQg71KZUpyJdcBWr5zyTDKR92xA4obgM'
    },
    body: JSON.stringify({
      estado_atencion: estadoAtencion,
      updated_at: new Date().toISOString()
    })
  });
} catch (err) {
  console.warn('Error patching handover to Supabase:', err);
}

return JSON.stringify({
  status: 'handover_triggered',
  estado_registrado: estadoAtencion,
  alert: (estadoAtencion === 'ESCALADO_HUMANO') ? 'ALARMA_RECEPCION_ACTIVADA' : 'REGISTRADO_PENDIENTE_GUARDIA',
  mensaje: (estadoAtencion === 'ESCALADO_HUMANO') ? 'Se ha activado la alarma sonora en recepcion.' : 'Registrado como pendiente fuera de horario para atencion a primera hora hábil.'
});
